Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -62,9 +62,9 @@
 function selectRole(id){state.selected=roles.find(r=>r.id===id);document.querySelectorAll('.role-card').forEach(e=>e.classList.toggle('selected',e.dataset.role===id));$('selectedNote').innerHTML=`Calling chosen: <strong>${state.selected.name}</strong>`;$('beginBtn').disabled=false;}
 renderRoles();$('randomRole').onclick=()=>{let r=roles[Math.floor(Math.random()*roles.length)];selectRole(r.id);$('randomRole').textContent=`⚄ Fate chose ${r.name}`};$('beginBtn').onclick=startGame;
 function startGame(){const r=state.selected;if(!r)return;state={...state,role:r,hp:r.hp,maxHp:r.hp,resolve:r.resolve,maxResolve:r.resolve,scene:'road',enemy:null,inventory:['Brass key'],log:['The journey began in Emberfall.'],flags:{},turn:0};$('intro').style.display='none';$('ending').classList.remove('show');$('game').classList.add('active');render();window.scrollTo({top:0,behavior:'smooth'});}
 function addLog(text){state.log.unshift(text);if(state.log.length>7)state.log.pop()}
-function render(){const sc=scenes[state.scene];if(!sc)return;state.turn++;$('chapterLabel').textContent=`Chapter ${['I','II','III','IV'][Math.min(sc.chapter-1,3)]} · ${sc.chapter===1?'The Ashen Road':sc.chapter===2?'The Long Way North':sc.chapter===3?'The Tower at World’s End':'The Last Ember'}`;$('track').innerHTML=[1,2,3,4].map(n=>`<span class="track-dot ${n<=sc.chapter?'done':''}"></span>`).join('');$('heroIcon').textContent=state.role.icon;$('heroName').textContent=state.role.name;$('heroClass').textContent=state.role.skill;$('hpText').textContent=`${state.hp} / ${state.maxHp}`;$('hpBar').style.width=`${Math.max(0,state.hp)/state.maxHp*100}%`;$('resolveText').textContent=`${state.resolve} / ${state.maxResolve}`;$('resolveBar').style.width=`${Math.max(0,state.resolve)/state.maxResolve*100}%`;$('inventory').innerHTML=state.inventory.length?state.inventory.map(x=>`<span class="item-chip">✧ ${x}</span>`).join(''):'<span class="empty">Just you and your wits.</span>';$('logList').innerHTML=state.log.map(x=>`<div class="log-entry">${x}</div>`).join('');
+function render(){const sc=scenes[state.scene];if(!sc)return;if(sc.encounter&&!state.enemy){state.enemy=sc.encounter;state.enemyHp=enemies[sc.encounter].hp;state.enemyNext=sc.afterFight;state.enemyMessage='The guardian stirs. Choose your approach.';}state.turn++;$('chapterLabel').textContent=`Chapter ${['I','II','III','IV'][Math.min(sc.chapter-1,3)]} · ${sc.chapter===1?'The Ashen Road':sc.chapter===2?'The Long Way North':sc.chapter===3?'The Tower at World’s End':'The Last Ember'}`;$('track').innerHTML=[1,2,3,4].map(n=>`<span class="track-dot ${n<=sc.chapter?'done':''}"></span>`).join('');$('heroIcon').textContent=state.role.icon;$('heroName').textContent=state.role.name;$('heroClass').textContent=state.role.skill;$('hpText').textContent=`${state.hp} / ${state.maxHp}`;$('hpBar').style.width=`${Math.max(0,state.hp)/state.maxHp*100}%`;$('resolveText').textContent=`${state.resolve} / ${state.maxResolve}`;$('resolveBar').style.width=`${Math.max(0,state.resolve)/state.maxResolve*100}%`;$('inventory').innerHTML=state.inventory.length?state.inventory.map(x=>`<span class="item-chip">✧ ${x}</span>`).join(''):'<span class="empty">Just you and your wits.</span>';$('logList').innerHTML=state.log.map(x=>`<div class="log-entry">${x}</div>`).join('');
 let html=`<div class="scene-kicker">${sc.chapter===1?'The beginning':sc.chapter===2?'The road unfolds':sc.chapter===3?'At the threshold':'A choice that matters'}</div><div class="scene-art">${sc.icon}</div><h2>${sc.title}</h2><div class="story-copy">${sc.text.map(p=>`<p>${p}</p>`).join('')}</div>`;
 if(state.enemy){html+=combatHTML(state.enemy)}else if(sc.choices){html+=`<div class="choices">${sc.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><span class="choice-num">${i+1}</span><span class="choice-copy"><div class="choice-title">${c.title}</div><div class="choice-sub">${c.sub}</div></span><span class="choice-risk ${c.safe?'safe':''}">${c.risk||'Peaceful'}</span></button>`).join('')}</div>`;}
 if(state.lastRoll)html+=`<div class="dice-box show"><div class="d20">${state.lastRoll.n}</div><div class="dice-result"><strong>${state.lastRoll.title}</strong><br><span>${state.lastRoll.detail}</span></div></div>`;
 $('storyPanel').innerHTML=html;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(sc.choices[+b.dataset.choice]));if(state.enemy)bindCombat();}
